// Atomest Deterministic Validator & Sanitizer
const item = $input.first().json;

// Extract and trim fields
const fullName = (item.fullName || item.name || '').trim();
const email = (item.email || '').trim().toLowerCase();
const phoneRaw = (item.phone || '').trim();
const company = (item.company || '').trim();
const interest = (item.interest || 'General Inquiry').trim();
const message = (item.message || item.description || '').trim();
const consent = item.consent === true || item.consent === 'true' || item.consent === 1;

const errors = [];

// 1. Required Presence Validation
if (!fullName) errors.push('fullName is required.');
if (!email) errors.push('email is required.');
if (!message) errors.push('message is required.');

// 2. Strict Email Regex Validation
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (email && !emailRegex.test(email)) {
  errors.push('email syntax is invalid.');
}

// 3. Phone Normalization (E.164-compatible strip)
const sanitizedPhone = phoneRaw.replace(/[^0-9+]/g, '');

// 4. Honeypot Anti-Spam Check
if (item.hp_field && item.hp_field.length > 0) {
  errors.push('Spam bot detected via honeypot.');
}

const isValid = errors.length === 0;
const leadId = 'LEAD-' + Math.random().toString(36).substring(2, 9).toUpperCase();
const receivedAt = new Date().toISOString();

return {
  json: {
    isValid,
    leadId,
    receivedAt,
    errors,
    sanitized: {
      fullName,
      email,
      phone: sanitizedPhone,
      company: company || 'Not Specified',
      interest,
      message: message.substring(0, 1500), // Cap length for safety
      consent
    },
    rawPayload: item
  }
};

